class Solution {
    public boolean canPlaceFlowers(int[] flowerbed, int n) {
        for (int i = 0; i < flowerbed.length && n > 0; i++) {
            if (flowerbed[i] == 0
                    && (i == 0 || flowerbed[i - 1] == 0)
                    && (i == flowerbed.length - 1 || flowerbed[i + 1] == 0)) {
                flowerbed[i] = 1;
                n--;
            }
        }
        return n == 0;
    }
}

class Solution {
    public boolean canPlaceFlowers(int[] flowerbed, int n) {
        int canPlant = 0;
        int zeros = 1;
        for (int plot : flowerbed) {
            if (plot == 0) {
                zeros++;
            } else {
                canPlant += (zeros - 1) / 2;
                zeros = 0;
            }
        }
        zeros++;
        canPlant += (zeros - 1) / 2;
        return canPlant >= n;
    }
}

class Solution {
    public boolean canPlaceFlowers(int[] flowerbed, int n) {
        int lastPlanted = -2;
        for (int i = 0; i < flowerbed.length && n > 0; i++) {
            if (flowerbed[i] == 1) {
                lastPlanted = i;
                continue;
            }
            boolean leftClear = i - lastPlanted > 1;
            boolean rightClear = i == flowerbed.length - 1 || flowerbed[i + 1] == 0;
            if (leftClear && rightClear) {
                lastPlanted = i;
                n--;
            }
        }
        return n <= 0;
    }
}

class Solution {
    public boolean canPlaceFlowers(int[] flowerbed, int n) {
        int i = 0;
        while (i < flowerbed.length && n > 0) {
            if (flowerbed[i] == 1) {
                i += 2;
                continue;
            }
            boolean leftClear = i == 0 || flowerbed[i - 1] == 0;
            boolean rightClear = i == flowerbed.length - 1 || flowerbed[i + 1] == 0;
            if (leftClear && rightClear) {
                n--;
                i += 2;
            } else {
                i++;
            }
        }
        return n <= 0;
    }
}

class Solution {
    public boolean canPlaceFlowers(int[] flowerbed, int n) {
        Integer[][] memo = new Integer[flowerbed.length][2];
        return maxFlowers(0, false, flowerbed, memo) >= n;
    }

    private int maxFlowers(int index, boolean previousOccupied, int[] flowerbed, Integer[][] memo) {
        if (index == flowerbed.length) {
            return 0;
        }
        int state = previousOccupied ? 1 : 0;
        if (memo[index][state] != null) {
            return memo[index][state];
        }
        if (flowerbed[index] == 1) {
            memo[index][state] = maxFlowers(index + 1, true, flowerbed, memo);
            return memo[index][state];
        }

        int best = maxFlowers(index + 1, false, flowerbed, memo);
        boolean nextClear = index == flowerbed.length - 1 || flowerbed[index + 1] == 0;
        if (!previousOccupied && nextClear) {
            best = Math.max(best, 1 + maxFlowers(index + 1, true, flowerbed, memo));
        }
        memo[index][state] = best;
        return best;
    }
}
